import {
    getClientInformationEventType,
    pruneClientInformation,
} from "../app/src/utils/device/clientInformation";
import { MatrixClient } from "matrix-js-sdk/src/client";

describe("pruneClientInformation (scratch)", () => {
    const mkClient = (accountData: Record<string, MatrixEvent>) =>
        ({
            store: { accountData },
            deleteAccountData: jest.fn().mockResolvedValue(undefined),
        } as unknown as MatrixClient);

    it("deletes information of devices that are no longer present", () => {
        const client = mkClient({
            [getClientInformationEventType("DEV1")]: new MatrixEvent({ type: getClientInformationEventType("DEV1") }),
            [getClientInformationEventType("DEV2")]: new MatrixEvent({ type: getClientInformationEventType("DEV2") }),
            "m.other": new MatrixEvent({ type: "m.other" }),
        });

        pruneClientInformation(["DEV1"], client);

        expect(client.deleteAccountData).toHaveBeenCalledTimes(1);
        expect(client.deleteAccountData).toHaveBeenCalledWith(getClientInformationEventType("DEV2"));
    });

    it("does nothing without valid device ids", () => {
        const client = mkClient({
            [getClientInformationEventType("DEV1")]: new MatrixEvent({ type: getClientInformationEventType("DEV1") }),
        });

        pruneClientInformation([], client);
        expect(client.deleteAccountData).not.toHaveBeenCalled();
    });

    it("supports Map and array account data stores", () => {
        const map = new Map<string, MatrixEvent>();
        map.set(getClientInformationEventType("DEV1"), new MatrixEvent({ type: getClientInformationEventType("DEV1") }));
        map.set(getClientInformationEventType("DEV2"), new MatrixEvent({ type: getClientInformationEventType("DEV2") }));
        const mapClient = { store: { accountData: map }, deleteAccountData: jest.fn() } as unknown as MatrixClient;
        pruneClientInformation(["DEV1"], mapClient);
        expect(mapClient.deleteAccountData).toHaveBeenCalledWith(getClientInformationEventType("DEV2"));

        const arr = [new MatrixEvent({ type: getClientInformationEventType("DEV3") })];
        const arrClient = { store: { accountData: arr }, deleteAccountData: jest.fn() } as unknown as MatrixClient;
        pruneClientInformation(["DEV1"], arrClient);
        expect(arrClient.deleteAccountData).toHaveBeenCalledWith(getClientInformationEventType("DEV3"));
    });

    it("does not throw when the store has no account data", () => {
        const client = { store: {}, deleteAccountData: jest.fn() } as unknown as MatrixClient;
        expect(() => pruneClientInformation(["DEV1"], client)).not.toThrow();
    });
});
